    \node[myNodeNarrow, dashed, text width=2cm] (termC) at (2.5cm, -9.5cm) {Bound on Term C}; 
    \node[myNodeNarrow, dashed, text width=2cm] (termB) at (5cm, -9.5cm) {Bound on Term B}; 
    \node[myNodeNarrow, dashed, text width=2cm] (termA) at (7.5cm, -9.5cm) {Bound on Term A}; 

    \node[myNodeNarrow, dashed, text width=2.75cm] (technicalLemma) at (3.75cm, -11cm) {\cref{lem:SS:cdfratios}}; 

